import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { drizzle } from 'drizzle-orm/postgres-js';
import { migrate } from 'drizzle-orm/postgres-js/migrator';
import postgres from 'postgres';

/** Folder of SQL migrations generated by `drizzle-kit generate`. */
export const MIGRATIONS_FOLDER = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  '../drizzle',
);

/**
 * Apply every pending migration in order. Safe to run repeatedly: Drizzle
 * records applied migrations in drizzle.__drizzle_migrations and skips them.
 */
export async function runMigrations(databaseUrl: string): Promise<void> {
  // One connection; silence Postgres NOTICEs like "schema already exists".
  const sql = postgres(databaseUrl, { max: 1, onnotice: () => undefined });
  try {
    await migrate(drizzle(sql), { migrationsFolder: MIGRATIONS_FOLDER });
  } finally {
    await sql.end();
  }
}
